    if (event && ['已约定', '已改期'].includes(effect.state)) {
      event.date = effect.date; event.time = effect.time; event.location = effect.location;
      event.source_log_ids = { ...event.source_log_ids, [logId]: true };
      event.follow_up = `已确认约定：${effect.date} ${effect.time}，${effect.location}`;
    }
