// 只读宿主最后一个成功摄取的可见assistant选中页；不接受主模型/调用者传入的历史state。
function captureCgPrior({ Schema, cleanRoot, equal, resolveNarrativeSource, sourceResolver, getVariables, getChatMessages, getCurrentChatId, getMessageObject, source, messageId }) {
  const find = () => {
    try {
      if (String(getCurrentChatId()) !== String(source.chat_id) || !Number.isSafeInteger(Number(messageId)) || Number(messageId) <= 0) return null;
      const rows = getChatMessages(`0-${Number(messageId) - 1}`, { role: 'assistant', hide_state: 'unhidden', include_swipes: false });
      if (!Array.isArray(rows)) return null;
      for (const row of rows.slice().sort((a, b) => Number(b.message_id) - Number(a.message_id))) {
        if (row.role !== 'assistant' || row.is_hidden || !Number.isSafeInteger(Number(row.message_id)) || Number(row.message_id) < 0 || Number(row.message_id) >= Number(messageId)) continue;
        try {
          const object = getMessageObject(row.message_id), swipe = object?.swipe_id ?? 0;
          if (!object) continue;
          const actual = resolveNarrativeSource({ chat_id: source.chat_id, message_id: row.message_id }, sourceResolver);
          const data = getVariables({ type: 'message', message_id: row.message_id });
          if (!data?.stat_data) continue;
          const stat = Schema.parse(cleanRoot(data.stat_data));
          const ingest = stat.phone.context.ingest_records[`narrative:${actual.ref}`];
          if (!ingest || ingest.source_id !== actual.ref || ingest.fingerprint !== actual.fingerprint) continue;
          return { snapshot: { actual, stat }, object, swipe };
        } catch { /* 隐藏、失败、未摄取或不符合Schema的楼层不是受控历史快照；继续找更早成功楼。 */ }
      }
    } catch { /* 宿主无法安全提供范围/变量时不猜测历史资格；本楼新来源仍可建立资格。 */ }
    return null;
  };
  const prior = find();
  return { snapshot: prior?.snapshot ?? null, valid: () => {
    const current = find();
    return prior === null ? current === null : !!current && current.object === prior.object && current.swipe === prior.swipe && equal(current.snapshot, prior.snapshot);
  } };
}

